from pathlib import Path
import os, re

root = Path('src')
endpoint = os.environ.get('RIU_LICENSE_ENDPOINT', '').strip()
endpoint_cs = endpoint.replace('\\', '\\\\').replace('"', '\\"')

# App.xaml: startup is controlled by App.xaml.cs so MainWindow cannot open before license validation.
p = root / 'App.xaml'
s = p.read_text(encoding='utf-8')
s = re.sub(r'\s+StartupUri="[^"]+"', '', s)
p.write_text(s, encoding='utf-8')

# Mandatory startup gate. Closing activation exits the app; MainWindow is created only after success.
(root / 'App.xaml.cs').write_text('''using System.Windows;\n\nnamespace RiuClickerCS;\n\npublic partial class App : Application\n{\n    protected override async void OnStartup(StartupEventArgs e)\n    {\n        base.OnStartup(e);\n        ShutdownMode = ShutdownMode.OnExplicitShutdown;\n\n        var savedKey = LicenseService.LoadSavedKey();\n        if (!string.IsNullOrWhiteSpace(savedKey))\n        {\n            var check = await LicenseService.ValidateAsync(savedKey);\n            if (check.Ok)\n            {\n                OpenMainWindow();\n                return;\n            }\n            LicenseService.ClearSavedKey();\n        }\n\n        var activation = new ActivationWindow();\n        var ok = activation.ShowDialog() == true && activation.LicenseActivated;\n        if (!ok)\n        {\n            Shutdown();\n            return;\n        }\n\n        OpenMainWindow();\n    }\n\n    private void OpenMainWindow()\n    {\n        var main = new MainWindow();\n        MainWindow = main;\n        ShutdownMode = ShutdownMode.OnMainWindowClose;\n        main.Show();\n    }\n}\n''', encoding='utf-8')

(root / 'LicenseService.cs').write_text(f'''using Microsoft.Win32;\nusing System.IO;\nusing System.Net.Http;\nusing System.Security.Cryptography;\nusing System.Text;\nusing System.Text.Json;\n\nnamespace RiuClickerCS;\n\npublic sealed class LicenseResult\n{{\n    public bool Ok {{ get; set; }}\n    public string Message {{ get; set; }} = "";\n    public string Plan {{ get; set; }} = "";\n    public DateTimeOffset? ExpiresAt {{ get; set; }}\n}}\n\npublic static class LicenseService\n{{\n    public const string Endpoint = "{endpoint_cs}";\n    public const string LocalTestKey = "RIU-TEST-1000-0001";\n    private static readonly HttpClient Http = new() {{ Timeout = TimeSpan.FromSeconds(8) }};\n    private static readonly string Folder = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "RiuClicker");\n    private static readonly string LicenseFile = Path.Combine(Folder, "license.json");\n\n    public static string DeviceId()\n    {{\n        var machineGuid = "";\n        try\n        {{\n            using var key = Registry.LocalMachine.OpenSubKey(@"SOFTWARE\\Microsoft\\Cryptography");\n            machineGuid = key?.GetValue("MachineGuid")?.ToString() ?? "";\n        }}\n        catch {{ }}\n        var raw = string.Join("|", machineGuid, Environment.MachineName, Environment.ProcessorCount, Environment.OSVersion.VersionString);\n        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(raw));\n        return Convert.ToHexString(hash)[..24];\n    }}\n\n    public static string? LoadSavedKey()\n    {{\n        try\n        {{\n            if (!File.Exists(LicenseFile)) return null;\n            using var doc = JsonDocument.Parse(File.ReadAllText(LicenseFile));\n            return doc.RootElement.TryGetProperty("key", out var k) ? k.GetString() : null;\n        }}\n        catch {{ return null; }}\n    }}\n\n    public static void SaveKey(string key)\n    {{\n        Directory.CreateDirectory(Folder);\n        File.WriteAllText(LicenseFile, JsonSerializer.Serialize(new {{ key = Normalize(key) }}));\n    }}\n\n    public static void ClearSavedKey()\n    {{\n        try {{ if (File.Exists(LicenseFile)) File.Delete(LicenseFile); }} catch {{ }}\n    }}\n\n    public static Task<LicenseResult> ActivateAsync(string key, CancellationToken ct = default) => SendAsync("activate", key, ct);\n    public static Task<LicenseResult> ValidateAsync(string key, CancellationToken ct = default) => SendAsync("validate", key, ct);\n\n    private static async Task<LicenseResult> SendAsync(string action, string key, CancellationToken ct)\n    {{\n        key = Normalize(key);\n        if (key.Length < 12) return new() {{ Ok = false, Message = "Invalid license key format." }};\n\n        // Temporary local test gate until the real Firebase endpoint is configured.\n        // It still blocks MainWindow completely unless a valid key is entered.\n        if (string.IsNullOrWhiteSpace(Endpoint))\n        {{\n            if (string.Equals(key, LocalTestKey, StringComparison.Ordinal))\n                return new() {{ Ok = true, Message = "Local test license accepted.", Plan = "TEST" }};\n            return new() {{ Ok = false, Message = "Invalid key. License server is not configured yet." }};\n        }}\n\n        try\n        {{\n            var json = JsonSerializer.Serialize(new {{ action, key, deviceId = DeviceId(), app = "RiuClicker", version = "1.0" }});\n            using var req = new HttpRequestMessage(HttpMethod.Post, Endpoint) {{ Content = new StringContent(json, Encoding.UTF8, "application/json") }};\n            using var res = await Http.SendAsync(req, ct);\n            var body = await res.Content.ReadAsStringAsync(ct);\n            if (!res.IsSuccessStatusCode) return new() {{ Ok = false, Message = "License server error." }};\n            using var doc = JsonDocument.Parse(body);\n            var rootEl = doc.RootElement;\n            var result = new LicenseResult\n            {{\n                Ok = rootEl.TryGetProperty("ok", out var ok) && ok.GetBoolean(),\n                Message = rootEl.TryGetProperty("message", out var msg) ? msg.GetString() ?? "" : "",\n                Plan = rootEl.TryGetProperty("plan", out var plan) ? plan.GetString() ?? "" : ""\n            }};\n            if (rootEl.TryGetProperty("expiresAt", out var exp) && exp.ValueKind == JsonValueKind.String && DateTimeOffset.TryParse(exp.GetString(), out var dt)) result.ExpiresAt = dt;\n            return result;\n        }}\n        catch (TaskCanceledException) {{ return new() {{ Ok = false, Message = "License server timeout." }}; }}\n        catch {{ return new() {{ Ok = false, Message = "Could not connect to license server." }}; }}\n    }}\n\n    private static string Normalize(string key) => key.Trim().ToUpperInvariant().Replace(" ", "");\n}}\n''', encoding='utf-8')

(root / 'ActivationWindow.xaml').write_text('''<Window x:Class="RiuClickerCS.ActivationWindow"\n        xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"\n        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"\n        Title="RiuClicker 1.0 · License" Width="520" Height="390"\n        WindowStartupLocation="CenterScreen" ResizeMode="NoResize" Background="#090B13" Foreground="White">\n    <Grid Margin="30">\n        <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>\n        <StackPanel>\n            <TextBlock Text="RIUCLICKER 1.0" FontSize="12" FontWeight="Bold" Foreground="#22D3EE"/>\n            <TextBlock Text="Activate your license" FontSize="30" FontWeight="Bold" Margin="0,8,0,6"/>\n            <TextBlock Text="Enter your key. Without a valid key RiuClicker will not open." Foreground="#98A2B8" TextWrapping="Wrap" FontSize="14"/>\n        </StackPanel>\n        <Border Grid.Row="1" Margin="0,24,0,18" Padding="20" CornerRadius="18" Background="#121725" BorderBrush="#2A3347" BorderThickness="1">\n            <StackPanel VerticalAlignment="Center">\n                <TextBlock Text="LICENSE KEY" Foreground="#98A2B8" FontSize="11" FontWeight="Bold"/>\n                <TextBox x:Name="KeyBox" FontFamily="Consolas" FontSize="17" CharacterCasing="Upper" Margin="0,8,0,12" Height="44" VerticalContentAlignment="Center"/>\n                <Button x:Name="ActivateButton" Content="ACTIVATE LICENSE" Height="46" Click="Activate_Click" Background="#7C3AED" BorderBrush="#8B5CF6"/>\n                <TextBlock x:Name="StatusText" Margin="0,12,0,0" Foreground="#98A2B8" TextWrapping="Wrap" TextAlignment="Center"/>\n            </StackPanel>\n        </Border>\n        <Grid Grid.Row="2"><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition/></Grid.ColumnDefinitions><TextBlock Text="Device:" Foreground="#69758C"/><TextBlock x:Name="DeviceText" Grid.Column="1" Foreground="#8994AA" HorizontalAlignment="Right" FontFamily="Consolas"/></Grid>\n    </Grid>\n</Window>\n''', encoding='utf-8')

(root / 'ActivationWindow.xaml.cs').write_text('''using System.Windows;\n\nnamespace RiuClickerCS;\n\npublic partial class ActivationWindow : Window\n{\n    public bool LicenseActivated { get; private set; }\n    public ActivationWindow()\n    {\n        InitializeComponent();\n        DeviceText.Text = LicenseService.DeviceId();\n    }\n\n    private async void Activate_Click(object sender, RoutedEventArgs e)\n    {\n        var key = KeyBox.Text.Trim();\n        if (string.IsNullOrWhiteSpace(key)) { StatusText.Text = "Enter your license key."; return; }\n        ActivateButton.IsEnabled = false;\n        StatusText.Text = "Checking license...";\n        var result = await LicenseService.ActivateAsync(key);\n        ActivateButton.IsEnabled = true;\n        if (!result.Ok) { StatusText.Text = string.IsNullOrWhiteSpace(result.Message) ? "Activation failed." : result.Message; return; }\n        LicenseService.SaveKey(key);\n        LicenseActivated = true;\n        StatusText.Text = result.ExpiresAt is { } exp ? $"Activated · {result.Plan} · until {exp.LocalDateTime:d}" : $"Activated · {result.Plan}";\n        await Task.Delay(350);\n        DialogResult = true;\n        Close();\n    }\n}\n''', encoding='utf-8')

# Rename this line to RiuClicker 1.0 while retaining the restored 5.22 UI + Bolts functionality.
for name in ('MainWindow.xaml', 'MainWindow.xaml.cs', 'MainWindow.Extras.cs', 'BrandVisual.cs', 'Models.cs'):
    p = root / name
    if p.exists():
        text = p.read_text(encoding='utf-8').replace('5.23', '1.0')
        p.write_text(text, encoding='utf-8')

p = root / 'RiuClickerCS.csproj'
s = p.read_text(encoding='utf-8')
s = re.sub(r'<Version>[^<]+</Version>', '<Version>1.0.0</Version>', s)
s = re.sub(r'<FileVersion>[^<]+</FileVersion>', '<FileVersion>1.0.0.0</FileVersion>', s)
s = re.sub(r'<AssemblyVersion>[^<]+</AssemblyVersion>', '<AssemblyVersion>1.0.0.0</AssemblyVersion>', s)
p.write_text(s, encoding='utf-8')

print('Applied RiuClicker 1.0 mandatory license gate; endpoint configured=' + str(bool(endpoint)))
